const { spawnSync } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const r = spawnSync(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "whoamio"], {
  cwd: "/tmp", encoding: "utf8", timeout: 80000,
  env: { ...process.env, HOME: "/tmp", CI: "1", NO_COLOR: "1", FORCE_COLOR: "0", WRANGLER_SEND_METRICS: "false" }
});
if (r.error) broken("could not run wrangler: " + r.error.message);
const out = ((r.stdout || "") + (r.stderr || "")).replace(/\x1b\[[0-9;]*m/g, "");
if (!out.includes("Unknown argument: whoamio")) broken("wrangler did not report the unknown command: " + out.slice(0, 500));
if (r.status === 0) broken("wrangler whoamio exited 0");
if (!out.includes('Did you mean "wrangler whoami"?')) symptom("wrangler whoamio prints no Did you mean suggestion");
console.log('OK: wrangler whoamio suggests Did you mean "wrangler whoami"?');

